// Shared helpers for every game: sounds, confetti, home button, progress,
// start/celebration screens. No network, no storage, no tracking.
const Juegos = (() => {
  // ---------- Sound (generated by the browser, no audio files) ----------
  let audioCtx = null;

  function getAudio() {
    if (!audioCtx) {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (!AudioCtx) return null;
      audioCtx = new AudioCtx();
    }
    if (audioCtx.state === "suspended") audioCtx.resume();
    return audioCtx;
  }

  function tone(freq, duration, { type = "sine", volume = 0.2, slideTo = null, delay = 0 } = {}) {
    const ac = getAudio();
    if (!ac) return;
    const start = ac.currentTime + delay;
    const osc = ac.createOscillator();
    const gain = ac.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, start);
    if (slideTo) osc.frequency.exponentialRampToValueAtTime(slideTo, start + duration);
    gain.gain.setValueAtTime(volume, start);
    gain.gain.exponentialRampToValueAtTime(0.001, start + duration);
    osc.connect(gain).connect(ac.destination);
    osc.start(start);
    osc.stop(start + duration + 0.05);
  }

  const sound = {
    pop() {
      tone(450 + Math.random() * 300, 0.14, { slideTo: 1300, volume: 0.25 });
    },
    star() {
      tone(880, 0.12, { type: "triangle" });
      tone(1320, 0.22, { type: "triangle", delay: 0.08 });
    },
    click() {
      tone(660, 0.08, { type: "square", volume: 0.08 });
    },
    oops() {
      tone(300, 0.2, { type: "triangle", slideTo: 200, volume: 0.15 });
    },
    win() {
      [523, 659, 784, 1047].forEach((f, i) =>
        tone(f, 0.35, { type: "triangle", delay: i * 0.14, volume: 0.25 })
      );
    },
  };

  // ---------- Visual effects ----------
  const CONFETTI_COLORS = ["#f43f5e", "#f59e0b", "#22c55e", "#3b82f6", "#a855f7", "#ec4899"];

  function removeOnEnd(el) {
    el.addEventListener("animationend", () => el.remove(), { once: true });
  }

  // Small emoji particles flying out of a point (e.g. a popped bubble).
  function burst(x, y, emoji = "✨", count = 8) {
    for (let i = 0; i < count; i++) {
      const p = document.createElement("div");
      p.className = "particle";
      p.textContent = emoji;
      const angle = (Math.PI * 2 * i) / count;
      const dist = 70 + Math.random() * 50;
      p.style.left = `${x - 14}px`;
      p.style.top = `${y - 14}px`;
      p.style.setProperty("--dx", `${Math.cos(angle) * dist}px`);
      p.style.setProperty("--dy", `${Math.sin(angle) * dist}px`);
      document.body.appendChild(p);
      removeOnEnd(p);
    }
  }

  // Confetti rain over the whole screen.
  function confetti(count = 80) {
    for (let i = 0; i < count; i++) {
      const c = document.createElement("div");
      c.className = "confetti";
      c.style.left = `${Math.random() * window.innerWidth}px`;
      c.style.top = `${-30 - Math.random() * 60}px`;
      c.style.background = CONFETTI_COLORS[i % CONFETTI_COLORS.length];
      c.style.animationDelay = `${Math.random() * 0.4}s`;
      c.style.setProperty("--dx", `${(Math.random() - 0.5) * 200}px`);
      c.style.setProperty("--dy", `${window.innerHeight * (0.7 + Math.random() * 0.4)}px`);
      c.style.setProperty("--rot", `${Math.random() * 720}deg`);
      document.body.appendChild(c);
      removeOnEnd(c);
    }
  }

  // ---------- UI pieces ----------
  function homeButton(href = "../index.html") {
    const a = document.createElement("a");
    a.href = href;
    a.className = "home-btn";
    a.textContent = "🏠";
    a.setAttribute("aria-label", "Volver al inicio");
    document.body.appendChild(a);
  }

  // A row of `total` stars; call set(n) to light the first n.
  function progress(total, emoji = "⭐") {
    const bar = document.createElement("div");
    bar.className = "progress";
    const stars = [];
    for (let i = 0; i < total; i++) {
      const s = document.createElement("span");
      s.textContent = emoji;
      bar.appendChild(s);
      stars.push(s);
    }
    document.body.appendChild(bar);
    return {
      set(n) {
        stars.forEach((s, i) => s.classList.toggle("on", i < n));
      },
    };
  }

  function medals() {
    const box = document.createElement("div");
    box.className = "medals";
    document.body.appendChild(box);
    return {
      add(emoji = "🏅") {
        box.textContent += emoji;
      },
    };
  }

  // A fixed case: slots represent levels, not an ever-growing list of wins.
  // Race games may override the award with the prize for the child's place.
  function trophies(levelCount, { label = "Nivel" } = {}) {
    if (levelCount !== 3 && levelCount !== 4) throw new RangeError("Expected 3 or 4 trophy slots");
    const sequence = levelCount === 3 ? ["bronze", "gold", "cup"] : ["bronze", "silver", "gold", "cup"];
    const names = { bronze: "bronce", silver: "plata", gold: "oro", cup: "trofeo", participation: "medalla" };
    const colors = { bronze: "#c97d43", silver: "#b7c6d0", gold: "#ffcc58", cup: "#ffcc58", participation: "#55cbd1" };
    const box = document.createElement("div");
    box.className = "trophies";
    box.setAttribute("role", "group");
    box.setAttribute("aria-label", "Vitrina de premios");
    document.body.appendChild(box);

    // Inline SVG avoids missing emoji fonts on school computers and headless Chrome.
    function icon(prize) {
      const el = document.createElement("span");
      el.className = "trophy-icon";
      el.innerHTML = prize === "cup"
        ? `<svg viewBox="0 0 64 80" aria-hidden="true"><g stroke="#24334b" stroke-width="3" stroke-linejoin="round" stroke-linecap="round"><path d="M17 17H6v5c0 12 8 17 17 17M47 17h11v5c0 12-8 17-17 17" fill="none"/><path d="M17 9h30v19c0 14-7 21-15 21s-15-7-15-21z" fill="#ffcc58"/><path d="M32 49v12M22 62h20l3 9H19z" fill="#e9a941"/><path d="m32 19 2.5 5 5.5.8-4 4 .9 5.5-4.9-2.6-4.9 2.6.9-5.5-4-4 5.5-.8z" fill="#fff7e4"/></g></svg>`
        : `<svg viewBox="0 0 64 80" aria-hidden="true"><g stroke="#24334b" stroke-width="3" stroke-linejoin="round"><path d="M12 7h15l10 26-13 6z" fill="#ef6b61"/><path d="M37 7h15L40 39l-13-6z" fill="#55cbd1"/><circle cx="32" cy="49" r="21" fill="${colors[prize]}"/><circle cx="32" cy="49" r="16" fill="none" opacity=".35"/><path d="m32 36 3.7 7.5 8.3 1.2-6 5.9 1.4 8.3-7.4-3.9-7.4 3.9 1.4-8.3-6-5.9 8.3-1.2z" fill="#fff7e4"/></g></svg>`;
      return el;
    }

    const counts = sequence.map(() => 0);
    const slots = sequence.map((prize, index) => {
      const slot = document.createElement("div");
      slot.className = "trophy-slot";
      slot.dataset.award = prize;
      slot.dataset.filled = "false";
      slot.setAttribute("role", "img");
      slot.setAttribute("aria-label", `${label} ${index + 1}: pendiente`);
      slot.appendChild(icon(prize));
      box.appendChild(slot);
      return slot;
    });

    return {
      async award(index, { prize = sequence[index], text, blocking = true } = {}) {
        if (!Number.isInteger(index) || !slots[index] || !Object.hasOwn(names, prize)) {
          throw new RangeError("Invalid trophy slot or prize");
        }
        const slot = slots[index];
        let reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
        let from, flying;
        if (blocking) {
          const big = icon(prize);
          big.setAttribute("role", "img");
          big.setAttribute("aria-label", names[prize]);
          const celebration = celebrate(big, text);
          from = big.getBoundingClientRect();
          await celebration;
          reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
        } else {
          // Arcade games continue accepting input while the award is displayed.
          sound.win();
          if (!reduced) {
            flying = icon(prize);
            flying.classList.add("trophy-flight");
            flying.setAttribute("role", "img");
            flying.setAttribute("aria-label", names[prize]);
            Object.assign(flying.style, { left: `${innerWidth / 2 - 70}px`, top: `${innerHeight / 2 - 90}px`, width: "140px", height: "180px" });
            document.body.appendChild(flying);
            from = flying.getBoundingClientRect();
          }
        }
        if (!reduced) {
          const to = slot.getBoundingClientRect();
          if (!flying) {
            flying = icon(prize);
            flying.classList.add("trophy-flight");
            Object.assign(flying.style, { left: `${from.left}px`, top: `${from.top}px`, width: `${from.width}px`, height: `${from.height}px` });
            document.body.appendChild(flying);
          }
          const dx = to.left + to.width / 2 - from.left - from.width / 2;
          const dy = to.top + to.height / 2 - from.top - from.height / 2;
          const end = `translate(${dx}px, ${dy}px) scale(${Math.min(to.width / from.width, to.height / from.height)})`;
          const frames = blocking
            ? [{ transform: "translate(0, 0) scale(1)" }, { transform: end }]
            : [{ transform: "translate(0, 0) scale(1)", offset: 0 }, { transform: "translate(0, 0) scale(1)", offset: 0.35 }, { transform: end, offset: 1 }];
          const animation = flying.animate(frames, { duration: blocking ? 700 : 1100, easing: "ease-in-out", fill: "forwards" });
          await animation.finished.catch(() => {});
          flying.remove();
        }
        counts[index]++;
        slot.dataset.award = prize;
        slot.dataset.filled = "true";
        slot.dataset.count = String(counts[index]);
        slot.setAttribute("aria-label", `${label} ${index + 1}: ${names[prize]}${counts[index] > 1 ? `, ${counts[index]} veces` : ""}`);
        slot.replaceChildren(icon(prize));
        if (counts[index] > 1) {
          const count = document.createElement("span");
          count.className = "trophy-count";
          count.textContent = `×${counts[index]}`;
          slot.appendChild(count);
        }
      },
    };
  }

  // Overlay with a big emoji (or element), an optional result line and a green
  // play button. Resolves on click.
  function overlay(emoji, text) {
    return new Promise((resolve) => {
      const layer = document.createElement("div");
      layer.className = "overlay";
      const big = document.createElement("div");
      big.className = "big-emoji";
      if (emoji instanceof Node) big.appendChild(emoji);
      else big.textContent = emoji;
      const btn = document.createElement("button");
      btn.className = "play-btn";
      btn.textContent = "▶";
      btn.setAttribute("aria-label", "Jugar");
      btn.addEventListener("click", () => {
        sound.click();
        layer.remove();
        resolve();
      });
      layer.append(big);
      if (text) {
        const line = document.createElement("div");
        line.className = "overlay-text";
        line.textContent = text;
        layer.append(line);
      }
      layer.append(btn);
      document.body.appendChild(layer);
    });
  }

  function startScreen(emoji) {
    return overlay(emoji);
  }

  function celebrate(emoji = "🎉", text) {
    sound.win();
    confetti();
    return overlay(emoji, text);
  }

  // Right-click shows a friendly "green button" hint instead of a menu.
  function guardRightClick() {
    window.addEventListener("contextmenu", (e) => {
      e.preventDefault();
      sound.oops();
      const hint = document.createElement("div");
      hint.className = "wrong-button-hint";
      hint.textContent = "🟢🖱️";
      hint.style.left = `${e.clientX}px`;
      hint.style.top = `${e.clientY}px`;
      document.body.appendChild(hint);
      removeOnEnd(hint);
    });
  }

  function bubbleIcon() {
    const el = document.createElement("span");
    el.className = "bubble-look bubble-icon";
    return el;
  }

  function random(min, max) {
    return min + Math.random() * (max - min);
  }

  function pick(list) {
    return list[Math.floor(Math.random() * list.length)];
  }

  return { sound, burst, confetti, homeButton, progress, medals, trophies, overlay, startScreen, celebrate, guardRightClick, bubbleIcon, random, pick };
})();
